const ROLE_PERMISSION_BASE = {
  electrician: "mechanic",
  welder: "mechanic",
  turner: "mechanic",
  forkliftDriver: "mechanic",
  safetyEngineer: "engineer",
  energyEngineer: "engineer",
  designEngineer: "engineer",
  mechanicalEngineer: "engineer",
  instrumentationEngineer: "engineer",
  generalDirector: "productionDirector",
  technicalDirector: "director"
};

function permissionBaseRole(role) {
  return ROLE_PERMISSION_BASE[role] || role;
}

function isPrimaryAdminEngineer(user = null) {
  return [user, authenticatedProfile, profile].filter(Boolean).some(candidate =>
    String(candidate.employeeId || "").trim() === PRIMARY_ADMIN_ENGINEER_EMPLOYEE_ID
    && ["editor", "engineer"].includes(String(candidate.editorOriginalRole || candidate.role || ""))
  );
}

function hasEngineerInboxAccess(user = profile) {
  return permissionBaseRole(user?.role) === "engineer" || isPrimaryAdminEngineer(user);
}

function canonicalWorkerRole(role) {
  return role === "electrician" ? "mechanic" : role;
}

function isElectromechanicRole(role) {
  return role === "mechanic" || role === "electrician";
}

const RESOLUTION_EXECUTOR_ROLES = new Set(["mechanic", "electrician", "welder", "turner", "forkliftDriver"]);

function isResolutionExecutorRole(role) {
  return RESOLUTION_EXECUTOR_ROLES.has(String(role || ""));
}

function sameWorkerRole(left, right) {
  return canonicalWorkerRole(left) === canonicalWorkerRole(right);
}

function visibleRoleEntries() {
  return Object.entries(ROLE_ACCESS).filter(([role]) => role !== "electrician");
}
