    sourceName: profile?.name || "",
    sourcePhone: profile?.phone || "",
    requestedQty: requestItemsTotal(items) || 1,
    kind: "tmc",
    status: "created",
    whatsappOnly: true,
    whatsappSent: false,
    reportOnly: true,
