    apiJson("/api/admin/qr-routes").then(data => { const host=ui.adminMaintenancePanel?.querySelector("[data-admin-qr-route-list]"); if(!host)return; const routes=data.routes||[]; host.innerHTML=routes.length?routes.map(route=>`<article class="${route.active===false?"archived":""}"><div><strong>${escapeHtml(route.name)}</strong><span>${route.group==="operational"?"Операторы и начальники":"Инженеры и электромеханики"} · ${escapeHtml(route.area||"Все участки")}</span><small>Точек: ${(route.points||[]).length} · сотрудников: ${(route.userIds||[]).length||"все"}</small></div>${route.active===false?`<b>Архив</b>`:`<button type="button" class="danger no-print" data-archive-qr-route="${escapeHtml(route.id)}">Архивировать</button>`}</article>`).join(""):`<div class="empty-state">Маршрутов пока нет.</div>`; host.querySelectorAll("[data-archive-qr-route]").forEach(button=>button.addEventListener("click",async()=>{const reason=window.prompt("Причина архивирования маршрута:")?.trim();if(!reason)return;const password=window.prompt("Пароль администратора:");if(!password)return;await apiJson("/api/admin/qr-routes",{method:"POST",body:JSON.stringify({action:"archive",id:button.dataset.archiveQrRoute,reason,password})});renderAdminMaintenance();})); }).catch(()=>{});
