ui.qrWalkButton?.addEventListener("click", async () => {
  if (!isProfileReady()) {
    window.alert("Сначала войдите в ППР.");
    return;
  }
  if (!canEditChecklist()) {
    window.alert("Для обхода нужна роль, которой разрешено отмечать узлы.");
    return;
  }
  setButtonBusy(ui.qrWalkButton, true, "Открываем камеру...");
  try {
    while (true) {
      const parsed = await scanNodeQrCode(null, null, null);
      if (!parsed) break;
      if (parsed.kind === "gpm") {
        current.selectedGpmId = parsed.gpmId;
        current.gpmJournalKind = gpmItemKind(parsed.item);
        current.gpmScanMode = parsed.mode;
        current.gpmInspectionStep = parsed.mode === "forklift" ? "mode" : "decision";
        show("gpm", false);
        break;
      }
      const shift = currentWalkShift();
      await refreshQrWalkStatusFromServer(parsed.equipmentId, shift);
      if (isNodeShiftChecked(getRecord(parsed.equipmentId, parsed.nodeIndex, shift.date), shift.key)) {
        await openRepeatedNodeQrDestination(parsed, shift);
        break;
      }
      const action = await promptQrWalkDecision(parsed);
      if (action === "comment-saved") {
        show(homeViewForProfile(profile?.role), false);
        showAppToast("Комментарий отправлен. Обход этой смены засчитан.");
        break;
      }
      if (action === "finish") break;
    }
  } finally {
    if (ui.qrWalkButton?.isConnected) setButtonBusy(ui.qrWalkButton, false);
  }
});

